   bookUrl:SQ_bookUrl(id,S),coverUrl:SQ_S(b.imgUrl||""),
   intro:SQ_plain(b.desc),kind:kind.join(","),wordCount:SQ_wan(b.wordCount),
   lastChapter:"",status:SQ_status(b.state)});
